(function(){const still=window.matchMedia("(prefers-reduced-motion: reduce)");function start(band){let quotes=Array.from(band.querySelectorAll(".bb-reviews__quotes > blockquote"));const dotsBar=band.querySelector(".bb-reviews__dots");const count=parseInt(band.dataset.reviewCount,10);if(count>0&&dotsBar){const pool=quotes.map((quote,index)=>({quote,dot:dotsBar.children[index]}));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
const drawn=pool.slice(0,Math.min(count,pool.length));band.querySelector(".bb-reviews__quotes").replaceChildren(...drawn.map((row)=>row.quote));dotsBar.replaceChildren(...drawn.map((row)=>row.dot));quotes=drawn.map((row)=>row.quote);quotes.forEach((quote,index)=>{quote.classList.toggle("is-current",index===0);quote.setAttribute("aria-hidden",index===0?"false":"true");dotsBar.children[index].setAttribute("aria-pressed",index===0?"true":"false");dotsBar.children[index].querySelector("span").textContent=band.dataset.reviewLabel.replace("%d",String(index+1));});}
const interval=parseInt(band.dataset.interval,10)||7000;let current=0;let wanted=0;let turning=false;let animation=null;let generation=0;let timer=0;let visible=false;const measure=()=>band.style.setProperty("--bb-band-height",band.offsetHeight+"px");measure();new ResizeObserver(measure).observe(band);window.bluebirdSun(band.querySelector(".bb-reviews__sun"),band,()=>band.offsetWidth<600?{risen:[0,0],set:[20,band.offsetHeight-40],wander:[8,14],bow:10,duration:28000,}:{risen:[0,-30],set:[70,band.offsetHeight-60],wander:[18,16],bow:20,duration:28000,},);if(quotes.length<2||!dotsBar){return;}
const dots=Array.from(dotsBar.querySelectorAll("button"));function commit(index){current=index;quotes.forEach((quote,i)=>{quote.classList.toggle("is-current",i===current);quote.setAttribute("aria-hidden",i===current?"false":"true");});}
async function turn(manual){const run=++generation;turning=true;try{while(wanted!==current){animation=quotes[current].animate([{opacity:1},{opacity:0}],{duration:manual?150:350,easing:"ease",fill:"forwards",});await animation.finished;if(run!==generation){return;}
commit(wanted);animation.cancel();animation=quotes[current].animate([{opacity:0},{opacity:1}],{duration:manual?250:350,easing:"ease",});await animation.finished;if(run!==generation){return;}
manual=true;}}catch(error){if(error.name!=="AbortError"){throw error;}}finally{if(run===generation){animation=null;turning=false;schedule();}}}
function show(index,manual=true){wanted=(index+quotes.length)%quotes.length;window.clearTimeout(timer);dots.forEach((dot,i)=>dot.setAttribute("aria-pressed",i===wanted?"true":"false"));if(still.matches){generation++;animation?.cancel();animation=null;turning=false;commit(wanted);schedule();}else if(!turning&&wanted!==current){void turn(manual);}else if(!turning){schedule();}}
function schedule(){window.clearTimeout(timer);band.classList.toggle("is-resting",!visible||document.hidden);if(visible&&!turning&&!still.matches&&!document.hidden){timer=window.setTimeout(()=>show(current+1,false),interval);}}
dots.forEach((dot,i)=>dot.addEventListener("click",()=>show(i)));window.bluebirdSwipe(band,(step)=>show(wanted+step));band.querySelectorAll(".bb-turn").forEach((turn)=>{turn.addEventListener("click",()=>show(wanted+(turn.classList.contains("bb-turn--back")?-1:1)),);turn.hidden=false;});window.bluebirdSwipe.keys(dotsBar,(step)=>{show(wanted+step);dots[wanted].focus();});dotsBar.hidden=false;quotes.forEach((quote,i)=>quote.setAttribute("aria-hidden",i===current?"false":"true"),);new IntersectionObserver((entries)=>{visible=entries[0].isIntersecting;schedule();}).observe(band);document.addEventListener("visibilitychange",schedule);still.addEventListener("change",()=>{if(still.matches){show(wanted);}else{schedule();}});}
document.querySelectorAll(".bb-reviews").forEach(start);})();